export const meta = {
  name: 'structured-abstraction-review',
  description: 'Assess whether QuestionnaireV2 structured/core abstraction is over-engineered and what could be simpler',
  phases: [
    { title: 'Evidence', detail: '5 parallel readers: inventory, usage census, requirements, boilerplate, test leverage' },
    { title: 'Analysis', detail: 'simplification proposal vs steelman defense' },
    { title: 'Verify', detail: 'adversarial check of each simplification claim' },
  ],
}

const ROOT = '/Users/bodhishthomas/code/care_fe'
const CORE = ROOT + '/src/components/QuestionnaireV2/structured'

const COMMON = `You are reviewing the "structured" abstraction in the CARE frontend repo at ${ROOT}.
The abstraction lives at ${CORE}/ with subdirs: core/ (generic row-list editing engine), types/ (11 per-entity model.ts+Editor.tsx pairs: allergyIntolerance, medicationRequest, medicationStatement, symptom, diagnosis, appointment, encounter, serviceRequest, chargeItem, files, timeOfDeath), definitions/ (glue), shared/ (responseTemplates etc), plus registry.ts/types.ts/pluginRegistry.ts one level up.
There is a detailed architecture README at ${CORE}/core/README.md — read it for orientation but verify claims against actual source.
The review question from the module's author: "Do we need that level of complication? Can it be simpler?"
Your final text/structured output is data for a synthesizing reviewer, not a human-facing message. Be precise, cite file paths with line numbers, and quantify wherever possible.`

phase('Evidence')

const INVENTORY_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: {
    files: { type: 'array', items: { type: 'object', properties: { path: {type:'string'}, lines: {type:'number'}, purpose: {type:'string'} }, required: ['path','lines','purpose'] } },
    concepts: { type: 'array', items: { type: 'object', properties: { name: {type:'string'}, whereDefined: {type:'string'}, whatItDoes: {type:'string'}, whyItExists: {type:'string'}, complexityCost: {type:'string'} }, required: ['name','whereDefined','whatItDoes','whyItExists','complexityCost'] } },
    layeringAssessment: { type: 'string' },
    rawComplexityHotspots: { type: 'array', items: {type:'string'} },
  },
  required: ['files','concepts','layeringAssessment','rawComplexityHotspots'],
}

const CENSUS_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: {
    entries: { type: 'array', items: { type: 'object', properties: {
      name: {type:'string'},
      kind: {type:'string', description: 'export | hook-option | controller-field | component-prop'},
      consumers: {type:'array', items:{type:'string'}},
      consumerCount: {type:'number'},
      classification: {type:'string', enum: ['used-by-many','used-by-few','used-by-one','used-by-zero']},
      note: {type:'string'},
    }, required: ['name','kind','consumers','consumerCount','classification','note'] } },
    deadOrSpeculative: { type: 'array', items: {type:'string'} },
    summary: {type:'string'},
  },
  required: ['entries','deadOrSpeculative','summary'],
}

const REQUIREMENTS_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: {
    requirements: { type: 'array', items: { type: 'object', properties: {
      name: {type:'string'},
      status: {type:'string', enum: ['shipped-and-exercised','shipped-but-marginal','speculative']},
      evidence: {type:'string'},
      coreMachineryItForces: {type:'string'},
    }, required: ['name','status','evidence','coreMachineryItForces'] } },
    summary: {type:'string'},
  },
  required: ['requirements','summary'],
}

const BOILERPLATE_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: {
    perType: { type: 'array', items: { type: 'object', properties: {
      type: {type:'string'},
      modelLines: {type:'number'}, editorLines: {type:'number'},
      domainLogicShare: {type:'string'}, boilerplateShare: {type:'string'},
      wouldSimplerCoreHelp: {type:'string'},
    }, required: ['type','modelLines','editorLines','domainLogicShare','boilerplateShare','wouldSimplerCoreHelp'] } },
    crossTypeDuplication: { type: 'array', items: {type:'string'} },
    summary: {type:'string'},
  },
  required: ['perType','crossTypeDuplication','summary'],
}

const TESTS_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: {
    pinnedBehaviors: { type: 'array', items: { type: 'object', properties: {
      behavior: {type:'string'}, testFile: {type:'string'},
      realWorldTrigger: {type:'string'},
      verdict: {type:'string', enum: ['guards-real-bug','guards-plausible-bug','guards-speculative-case']},
    }, required: ['behavior','testFile','realWorldTrigger','verdict'] } },
    testToCodeRatio: {type:'string'},
    summary: {type:'string'},
  },
  required: ['pinnedBehaviors','testToCodeRatio','summary'],
}

const [inventory, census, requirements, boilerplate, testLeverage] = await parallel([
  () => agent(`${COMMON}

TASK: Produce a complete inventory of ${CORE}/core/ (source files, NOT test files — but note test file sizes).
Read every non-test file in core/. For each conceptual mechanism (RowId minting, EditLog + applyEditToLog coalescing table, projectRows, orphan pruning, resolveChanges, rowMutations, duplicates, droppedRowsNotice, useStructuredRows effects, StructuredList shell, error matching, AddEntityControl, RowStatusSelect, deepEqualJson, singleton mode, etc.) record: what it does, why it exists (from comments/README), and its complexity cost (LOC, number of invariants callers must know, coupling).
Also assess the layering (core -> types -> definitions -> registry): is the indirection earning its keep or is it ceremony?
List the raw complexity hotspots — the places a new contributor would most likely misuse or be confused by.`, { label: 'core-inventory', phase: 'Evidence', schema: INVENTORY_SCHEMA }),

  () => agent(`${COMMON}

TASK: Usage census. For EVERY public surface of the core, count real consumers across the codebase:
1. Every export of ${CORE}/core/ modules (functions, components, types).
2. Every field of StructuredRowsOptions (questionId, baseline, projectValues, mode, softDelete, duplicateKey, displayOrder, normalizePatch, isEmptyRow, createSeed, singletonRowId, initialEdits, disabled).
3. Every field of the returned controller (rows, addRow, addRows, updateRow, removeRow, isDuplicate, row, setRow, clearRow, edits, isDirty, droppedEdits, applyEdit, resetEdits).
4. Every prop of StructuredList / StructuredColumn (including errorFieldKeys, ownsErrorDisplay, headerHidden, mobileHidden, rowActions, canRemoveRow, rowDisabled, rowTitle...).
Use grep across ${ROOT}/src (exclude test files for the consumer count but note test-only usage separately). Classify each: used-by-many (4+ types), used-by-few (2-3), used-by-one, used-by-zero (only tests or nothing).
Flag anything that looks speculative/defensive with no production caller (e.g. truncateToSingletonRow multi-row branch, dedupeEditsFirstAppearance, displayOrder, normalizePatch...). Be exhaustive — this census is the backbone of the review.`, { label: 'usage-census', phase: 'Evidence', schema: CENSUS_SCHEMA }),

  () => agent(`${COMMON}

TASK: Requirements trace. The core's complexity is justified by claimed requirements. Verify each one is REAL (shipped, reachable, exercised by an actual user flow) vs marginal vs speculative:
1. Draft restore across reloads (read ${ROOT}/src/components/QuestionnaireV2/fill/draft/ — does the draft system really persist structured edit logs and restore them before baseline fetches resolve?)
2. AI fill assistant writing to unmounted editors baseline-blind (read ${ROOT}/src/components/QuestionnaireV2/fill/assistant/ — is this shipped/reachable in the product, or behind a flag?)
3. Soft-delete (entered_in_error) semantics and the phantom-row hazard (check which types configure softDelete and what the backend endpoints look like in ${ROOT}/src/types/emr/ or the types' toRequests).
4. Orphan pruning after background baseline refetch (when does baseline actually refetch mid-session?)
5. Singleton mode (appointment, time_of_death, encounter ?toDischarge seed).
6. Mobile/desktop parity of StructuredList.
7. Server error routing to row/field (row_id vs index matching).
8. initialEdits seeding (encounter ?toDischarge).
Also check git log for this module (git -C ${ROOT} log --oneline --follow on key files) to see whether the complexity was added in response to real bugs or upfront.
For each requirement state which core machinery it forces into existence, so the analysis phase can compute "if requirement X were dropped, machinery Y could go".`, { label: 'requirements-trace', phase: 'Evidence', schema: REQUIREMENTS_SCHEMA }),

  () => agent(`${COMMON}

TASK: Per-type boilerplate assessment. Read these representative pairs in full:
- ${CORE}/types/symptom/{model.ts,SymptomEditor.tsx} (claimed simplest)
- ${CORE}/types/diagnosis/{model.ts,DiagnosisEditor.tsx} (near-clone of symptom?)
- ${CORE}/types/medicationRequest/{model.ts,MedicationRequestEditor.tsx} (most complex)
- ${CORE}/types/appointment/ and ${CORE}/types/timeOfDeath/ (singleton mode)
- ${CORE}/types/encounter/ (singleton with seed)
Skim the remaining types' model.ts/Editor.tsx for line counts and structure.
For each: how many lines are genuine domain logic (field semantics, wire-shape building, validation) vs ceremony the abstraction demands (columns plumbing, controlProps spreading, error key wiring, projectValues, softDelete descriptors)?
Identify cross-type duplication: near-identical code repeated across types that a different abstraction (or a helper) would collapse. Also the inverse: places where the shared core forced awkward contortions on a type that plain bespoke code would express more simply.
Answer concretely: if core were replaced by something simpler, would each type's code get shorter, longer, or just different?`, { label: 'type-boilerplate', phase: 'Evidence', schema: BOILERPLATE_SCHEMA }),

  () => agent(`${COMMON}

TASK: Test-suite leverage audit. The core + types carry heavy test files (projectRows.test.ts 769 lines, editLog.test.ts 382, changes.test.ts 392, per-type model tests 400-1000 lines each).
Read the core test files and 2-3 per-type model tests. For each major pinned behavior, judge: does it guard a REAL bug a clinician could hit (state the user-visible trigger scenario), a plausible-but-unobserved bug, or a speculative case that only exists because the abstraction is this general?
Check git log/blame for hints that tests were added after real regressions (commit messages like 'fix(questionnaire-v2): ...').
Estimate the test-to-source ratio for core/ and for a typical type module.
The point: a heavily-tested invariant that only exists to defend the abstraction's own generality is evidence FOR simplification; a test pinning a real clinical-data hazard (duplicate records, phantom entered-in-error rows, lost drafts) is evidence the complexity is essential.`, { label: 'test-leverage', phase: 'Evidence', schema: TESTS_SCHEMA }),
])

log('Evidence gathered — running simplification proposal vs steelman defense')

phase('Analysis')

const EVIDENCE = JSON.stringify({ inventory, census, requirements, boilerplate, testLeverage })

const PROPOSAL_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: {
    verdictSummary: {type:'string'},
    claims: { type: 'array', items: { type: 'object', properties: {
      id: {type:'string'},
      title: {type:'string'},
      kind: {type:'string', enum: ['delete-machinery','collapse-layer','narrow-api','merge-duplication','simplify-mechanism','keep-as-is']},
      detail: {type:'string'},
      estimatedLocSaved: {type:'string'},
      risk: {type:'string'},
    }, required: ['id','title','kind','detail','estimatedLocSaved','risk'] } },
    alternativeDesign: {type:'string', description: 'sketch of what a materially simpler overall design would be, and what it would give up'},
  },
  required: ['verdictSummary','claims','alternativeDesign'],
}

const DEFENSE_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: {
    essentialComplexity: { type: 'array', items: { type: 'object', properties: {
      mechanism: {type:'string'}, whyEssential: {type:'string'}, whatBreaksWithoutIt: {type:'string'},
    }, required: ['mechanism','whyEssential','whatBreaksWithoutIt'] } },
    accidentalComplexityConceded: { type: 'array', items: {type:'string'} },
    overallPosition: {type:'string'},
  },
  required: ['essentialComplexity','accidentalComplexityConceded','overallPosition'],
}

const [proposal, defense] = await parallel([
  () => agent(`${COMMON}

You are the SIMPLIFIER. Five evidence reports (inventory, usage census, requirements trace, boilerplate assessment, test leverage) are below as JSON. Read them, spot-check the source where a claim matters, and produce concrete simplification claims.
Ground rules: a claim must name exactly what to delete/collapse/narrow, estimate LOC saved, and state the risk. Consider at minimum: (a) surfaces the census found used-by-zero or used-by-one; (b) layers that are pure pass-through ceremony; (c) cross-type duplication collapsible into helpers; (d) defensive machinery whose requirement the trace rated speculative; (e) whether the whole core could be replaced by a materially simpler design (e.g. per-editor local state + a thin shared edit-log util) given ONLY the requirements rated shipped-and-exercised — and honestly, what that would give up.
Do NOT pad with weak claims; 5-10 strong ones beat 20 weak ones. If the honest answer for some area is 'keep-as-is', say so with kind=keep-as-is.

EVIDENCE:
${EVIDENCE}`, { label: 'simplifier', phase: 'Analysis', schema: PROPOSAL_SCHEMA, effort: 'high' }),

  () => agent(`${COMMON}

You are the DEFENDER. Five evidence reports are below as JSON. Your job is the steelman: identify which complexity is ESSENTIAL — forced by real product requirements (clinical data safety, draft restore, AI assistant, soft-delete, server error mapping) — and state concretely what user-visible failure appears if each mechanism were removed. Spot-check source/tests where it matters.
Be honest: also concede the parts that genuinely are accidental complexity (speculative generality, dead surface, ceremony). A defense that concedes nothing is not credible.

EVIDENCE:
${EVIDENCE}`, { label: 'defender', phase: 'Analysis', schema: DEFENSE_SCHEMA, effort: 'high' }),
])

log(`Simplifier produced ${proposal.claims.length} claims — verifying the actionable ones`)

phase('Verify')

const VERDICT_SCHEMA = {
  type: 'object', additionalProperties: false,
  properties: {
    claimId: {type:'string'},
    verdict: {type:'string', enum: ['CONFIRMED','PARTIAL','REFUTED']},
    reasoning: {type:'string'},
    correctedLocEstimate: {type:'string'},
    breakage: {type:'string', description: 'what pinned test or user flow would break, if any'},
  },
  required: ['claimId','verdict','reasoning','correctedLocEstimate','breakage'],
}

const actionable = proposal.claims.filter(c => c.kind !== 'keep-as-is').slice(0, 6)
const verdicts = await parallel(actionable.map(c => () =>
  agent(`${COMMON}

You are an adversarial VERIFIER. Try to REFUTE this simplification claim by reading the actual source and tests. A claim is CONFIRMED only if the deletion/collapse is genuinely safe given shipped behavior and pinned tests; PARTIAL if a narrower version survives; REFUTED if the machinery is load-bearing. Check: real consumers (grep), tests that pin the behavior, and the defender's position below. Default to skepticism.

CLAIM (id=${c.id}): ${c.title}
KIND: ${c.kind}
DETAIL: ${c.detail}
CLAIMED LOC SAVED: ${c.estimatedLocSaved}
CLAIMED RISK: ${c.risk}

DEFENDER'S POSITION (for context):
${JSON.stringify(defense)}`, { label: `verify:${c.id}`, phase: 'Verify', schema: VERDICT_SCHEMA })
))

return {
  inventory, census, requirements, boilerplate, testLeverage,
  proposal, defense,
  verdicts: verdicts.filter(Boolean),
}

