1	import { deepEqualJson } from "./deepEqual";
2	import type { BaselineRow, EditLog, RowEdit, RowId } from "./types";
3	
4	/**
5	 * Builds the reducer's `baseline` map (and `projectRows`' equivalent
6	 * input) from the hook's `BaselineRow<TRow>[]`. `undefined` in,
7	 * `undefined` out — never coerced to an empty `Map`, which would be
8	 * misread as "this rowId is provably not on the server"
9	 * (`resolveOpAgainstBaseline`) instead of "not yet known".
10	 *
11	 * Pure: never mutates `baseline`.
12	 */
13	export function toBaselineMap<TRow extends object>(
14	  baseline: readonly BaselineRow<TRow>[] | undefined,
15	): ReadonlyMap<RowId, TRow> | undefined {
16	  if (baseline === undefined) return undefined;
17	  return new Map(baseline.map((entry) => [entry.rowId, entry.row] as const));
18	}
19	
20	/** Options for {@link applyEditToLog}. */
21	export interface ApplyEditOptions<TRow extends object> {
22	  /**
23	   * rowId → the unedited server row. Used to canonicalize an `update`
24	   * patch back to "no edit at all" once it matches what the server
25	   * already has — that is what makes "dirty" derived rather than sticky
26	   * (mild → moderate → mild leaves the section pristine).
27	   *
28	   * A rowId absent from this map (or the map itself absent) can never be
29	   * detected as "reverted" — by design. A row with no baseline entry is
30	   * an add, and an add was never on the server to revert to.
31	   */
32	  baseline?: ReadonlyMap<RowId, TRow>;
33	  /**
34	   * An ADDED row that satisfies this after an `update` replaces its patch
35	   * is annihilated — the row never reached the server, so clearing it
36	   * back to nothing is indistinguishable from never adding it. Applies
37	   * only to the existing-`add` × incoming-`update` cell, never to a
38	   * re-`add`, which is a fresh, deliberate creation.
39	   */
40	  isEmptyRow?: (row: TRow) => boolean;
41	}
42	
43	/**
44	 * Folds one more edit into the log, preserving the invariant the whole
45	 * state core depends on: **at most one entry per rowId, always**. This is
46	 * what makes "a clinician who never touched a section sends zero requests
47	 * for it" true by construction rather than by convention.
48	 *
49	 * Pure and total — never mutates `log` or an existing entry. The
50	 * assistant's edit path calls this same function, so human and assistant
51	 * input cannot diverge.
52	 *
53	 * Coalescing table (existing entry's op × incoming edit's op):
54	 *
55	 * | existing  | incoming `add`         | incoming `update`         | incoming `remove` |
56	 * |-----------|-------------------------|----------------------------|--------------------|
57	 * | *(none)*  | append `add`            | append `update`; drop if patch canonicalizes to baseline | append `remove` |
58	 * | `add`     | replace patch, stays `add` | replace patch, stays `add`; **annihilate instead if `isEmptyRow(patch)`** | **annihilate** (row never reached the server) |
59	 * | `update`  | **resolved against `baseline`** — `add` if the rowId provably isn't in it, else replace patch and stay `update` | replace patch, canonicalize against baseline, **drop if reverted** | replace with `remove` |
60	 * | `remove`  | **resolved against `baseline`** — `add` if the rowId provably isn't in it, else `update` (restore-and-patch) | same resolution as the `add` column | keep `remove` (idempotent) |
61	 *
62	 * The "resolved against `baseline`" cells never trust an op label as a
63	 * proxy for "this rowId is really on the server" — both labels are
64	 * forgeable by annihilation (see `resolveOpAgainstBaseline`); the
65	 * baseline map is the only source of truth consulted there.
66	 */
67	export function applyEditToLog<TRow extends object>(
68	  log: EditLog<TRow>,
69	  edit: RowEdit<TRow>,
70	  options: ApplyEditOptions<TRow> = {},
71	): EditLog<TRow> {
72	  const { baseline, isEmptyRow } = options;
73	  const index = log.findIndex((entry) => entry.rowId === edit.rowId);
74	
75	  if (index === -1) {
76	    return appendFresh(log, edit, baseline);
77	  }
78	
79	  const existing = log[index];
80	  const resolved = coalesce(existing, edit, baseline, isEmptyRow);
81	
82	  if (resolved === null) {
83	    // Annihilated (add→remove) — drop the slot, preserving the relative
84	    // order of every other entry.
85	    return [...log.slice(0, index), ...log.slice(index + 1)];
86	  }
87	
88	  const next = log.slice();
89	  next[index] = resolved;
90	  return next;
91	}
92	
93	function appendFresh<TRow extends object>(
94	  log: EditLog<TRow>,
95	  edit: RowEdit<TRow>,
96	  baseline: ReadonlyMap<RowId, TRow> | undefined,
97	): EditLog<TRow> {
98	  if (edit.op === "update" && isRevertedToBaseline(edit, baseline)) {
99	    // A no-op update against a known baseline is never recorded in the
100	    // first place — the section stays honestly pristine.
101	    return log.slice();
102	  }
103	  // Appends go to the end — add order is display order for added rows,
104	  // and this is the only path that grows the log's length.
105	  return [...log, edit];
106	}
107	
108	function coalesce<TRow extends object>(
109	  existing: RowEdit<TRow>,
110	  incoming: RowEdit<TRow>,
111	  baseline: ReadonlyMap<RowId, TRow> | undefined,
112	  isEmptyRow: ((row: TRow) => boolean) | undefined,
113	): RowEdit<TRow> | null {
114	  switch (existing.op) {
115	    case "add":
116	      return coalesceOntoAdd(existing, incoming, isEmptyRow);
117	    case "update":
118	      return coalesceOntoUpdate(existing, incoming, baseline);
119	    case "remove":
120	      return coalesceOntoRemove(existing, incoming, baseline);
121	  }
122	}
123	
124	function coalesceOntoAdd<TRow extends object>(
125	  existing: RowEdit<TRow>,
126	  incoming: RowEdit<TRow>,
127	  isEmptyRow: ((row: TRow) => boolean) | undefined,
128	): RowEdit<TRow> | null {
129	  if (incoming.op === "remove") {
130	    // The row never reached the server — there is nothing to tell it
131	    // about. Annihilate; the log returns to pristine for this rowId.
132	    return null;
133	  }
134	  // incoming is "add" (a re-add) or "update" — either way the row still
135	  // hasn't been created server-side, so it stays an `add`; `patch` is the
136	  // complete row, so this is a full replace.
137	  //
138	  // isEmptyRow applies only to the `update` case: an update that empties
139	  // an added row is the "clear it back out" gesture, and the row never
140	  // reached the server, so annihilating it is indistinguishable from
141	  // never adding it. A re-`add` is a deliberate creation and is never
142	  // annihilated by content.
143	  if (incoming.op === "update" && isEmptyRow?.(incoming.patch)) {
144	    return null;
145	  }
146	  return { rowId: existing.rowId, op: "add", patch: incoming.patch };
147	}
148	
149	function coalesceOntoUpdate<TRow extends object>(
150	  existing: RowEdit<TRow>,
151	  incoming: RowEdit<TRow>,
152	  baseline: ReadonlyMap<RowId, TRow> | undefined,
153	): RowEdit<TRow> | null {
154	  if (incoming.op === "remove") {
155	    return { rowId: existing.rowId, op: "remove", patch: incoming.patch };
156	  }
157	  if (incoming.op === "add") {
158	    // An existing `update` entry does not prove a real baseline row — the
159	    // label is forgeable by annihilation (see resolveOpAgainstBaseline) —
160	    // so resolve against the baseline map: keeping `add` here for a row
161	    // the server already has would instruct it to CREATE a duplicate
162	    // clinical record.
163	    const op = resolveOpAgainstBaseline(existing.rowId, baseline);
164	    return { rowId: existing.rowId, op, patch: incoming.patch };
165	  }
166	  // incoming is "update": replace the patch (always the complete row),
167	  // then canonicalize against baseline — the "edit-then-revert" case:
168	  // mild → moderate → mild must leave the section clean.
169	  if (
170	    isRevertedToBaseline(
171	      { rowId: existing.rowId, patch: incoming.patch },
172	      baseline,
173	    )
174	  ) {
175	    return null;
176	  }
177	  return { rowId: existing.rowId, op: "update", patch: incoming.patch };
178	}
179	
180	function coalesceOntoRemove<TRow extends object>(
181	  existing: RowEdit<TRow>,
182	  incoming: RowEdit<TRow>,
183	  baseline: ReadonlyMap<RowId, TRow> | undefined,
184	): RowEdit<TRow> | null {
185	  if (incoming.op === "remove") {
186	    return existing;
187	  }
188	  // incoming is "add" or "update": a resurrection of a row carrying a
189	  // pending `remove`. The existing `remove` does not prove the rowId is a
190	  // server row — `add(u) → remove(u)` annihilates the pair (erasing u's
191	  // history from the log), and a second `remove(u)` then reaches
192	  // `appendFresh`, which appends unconditionally — so the outcome is
193	  // resolved against the baseline map: `add` if the rowId provably isn't
194	  // a server row, `update` (restore-and-patch) otherwise. Both incoming
195	  // ops resolve identically, by data.
196	  //
197	  // Deliberate asymmetry with coalesceOntoUpdate: a restore whose patch
198	  // deep-equals the baseline row still records an `update` instead of
199	  // dropping it — remove-then-restore-unchanged is not treated as
200	  // "never happened".
201	  const op = resolveOpAgainstBaseline(existing.rowId, baseline);
202	  return { rowId: existing.rowId, op, patch: incoming.patch };
203	}
204	
205	/**
206	 * Decides what a resurrection/re-add op should BECOME, based on whether
207	 * the rowId is a row the server has — never on the op label the existing
208	 * entry or the incoming edit carries: annihilation erases a rowId's
209	 * history from the log, so both labels are forgeable (see the call sites
210	 * in `coalesceOntoRemove` and `coalesceOntoUpdate`). The baseline map is
211	 * the only source of truth consulted here.
212	 *
213	 * When `baseline` is not supplied there is genuinely no way to know, and
214	 * `"update"` is the documented, conservative fallback: a wrong `update`
215	 * surfaces as a loud 404/400, while a wrong `add` would silently create
216	 * a duplicate clinical row — data corruption, the worse failure. Every
217	 * real caller (via `useStructuredRows`) supplies the full map.
218	 */
219	function resolveOpAgainstBaseline<TRow extends object>(
220	  rowId: RowId,
221	  baseline: ReadonlyMap<RowId, TRow> | undefined,
222	): "add" | "update" {
223	  if (baseline === undefined) return "update";
224	  return baseline.has(rowId) ? "update" : "add";
225	}
226	
227	/**
228	 * Has this edit's patch collapsed back to exactly what the baseline
229	 * already holds for this rowId? Structural (JSON) equality, per
230	 * `deepEqualJson`'s doc comment — not `===`, since a patch is routinely
231	 * rebuilt as a fresh object (`{ ...baselineRow, field: value }`).
232	 *
233	 * Deliberately `false` when there is no baseline entry for this rowId
