  options: StructuredRowsOptions<TRow>,
): SingleRowController<TRow> {
  const internal = useStructuredRowsInternal(options, "single");
  return {
    row: internal.rows[0],
    droppedEdits: internal.droppedEdits,
    setRow: internal.setRow,
    clearRow: internal.clearRow,
  };
}

