42	    // real field key here).
43	    if (!error.field_key) return false;
44	    if (!fieldKeys.includes(error.field_key)) return false;
45	    if (error.row_id !== undefined) return error.row_id === rowId;
46	    if (error.index !== undefined)
47	      return rowIndex !== undefined && error.index === rowIndex;
48	    return rowId === undefined && rowIndex === undefined;
49	  });
50	}
