341	interface StructuredListRowProps<TRow extends object> {
342	  questionId: string;
343	  row: ProjectedRow<TRow>;
344	  rowIndex: number;
345	  columns: readonly StructuredColumn<TRow>[];
346	  errors: readonly QuestionValidationError[];
347	  listDisabled: boolean;
348	  onUpdateRow: (rowId: RowId, patch: Partial<TRow>) => void;
349	  onRemoveRow: (rowId: RowId) => void;
350	  rowTitle: (row: ProjectedRow<TRow>) => ReactNode;
351	  rowSummary?: (row: ProjectedRow<TRow>) => ReactNode;
352	  rowDisabled?: (row: ProjectedRow<TRow>) => boolean;
353	  rowClassName?: (row: ProjectedRow<TRow>) => string | undefined;
354	  removeLabel?: (row: ProjectedRow<TRow>) => string;
355	  canRemoveRow?: (row: ProjectedRow<TRow>) => boolean;
356	  rowActions?: (row: ProjectedRow<TRow>) => readonly StructuredRowAction[];
357	}
358	
359	/**
360	 * One row, as its own component — NOT inlined into a `.map()` closure in
361	 * `StructuredList` — so `update`/`handleRemove` can be genuine per-row
362	 * `useCallback`s (stable while `onUpdateRow`/`onRemoveRow`/`row.rowId` are
363	 * unchanged) instead of fresh arrows built every render inside a loop,
364	 * which feeds unstable identities into children's hook dependencies.
365	 * Mobile expand/collapse is local, per-row state; every row starts
366	 * collapsed EXCEPT when it carries a bound error (below).
367	 */
368	function StructuredListRow<TRow extends object>({
369	  questionId,
370	  row,
371	  rowIndex,
372	  columns,
373	  errors,
374	  listDisabled,
375	  onUpdateRow,
376	  onRemoveRow,
377	  rowTitle,
378	  rowSummary,
379	  rowDisabled,
380	  rowClassName,
381	  removeLabel,
382	  canRemoveRow,
383	  rowActions,
384	}: StructuredListRowProps<TRow>) {
385	  const { t } = useTranslation();
386	  const [expanded, setExpanded] = useState(false);
387	  const toggleExpanded = useCallback(() => setExpanded((value) => !value), []);
388	
389	  const update = useCallback(
390	    (patch: Partial<TRow>) => onUpdateRow(row.rowId, patch),
391	    [onUpdateRow, row.rowId],
392	  );
393	  const handleRemove = useCallback(
394	    () => onRemoveRow(row.rowId),
395	    [onRemoveRow, row.rowId],
396	  );
397	
398	  const isDisabled = listDisabled || (rowDisabled?.(row) ?? false);
399	  const canRemove = canRemoveRow?.(row) ?? !row.softDeleted;
400	  const removeText = removeLabel?.(row) ?? t("remove");
401	  // Built fresh every render (not memoized) — deliberately: a type's
402	  // `rowActions` closure typically closes over its own per-row state (e.g.
403	  // `openAddToTemplate(row.row)`), and this shell has no way to know that
404	  // closure's real dependencies. Cheap: a handful of plain objects, not a
405	  // hook, so there is no rules-of-hooks concern with it running
406	  // conditionally-shaped output on every render.
407	  const extraActions = rowActions?.(row) ?? [];
408	  const bodyId = `${questionId}--${row.rowId}--body`;
409	
410	  // One scan for every error-driven decision this row makes — the forced
411	  // expansion, the unmatched-key fallback, and the mobile re-print of a
412	  // `mobileHidden` cell's error (all three rendered below).
413	  const { hasError, unmatchedFieldKeys, mobileHiddenErrorColumns } = useMemo(
414	    () =>
415	      resolveRowErrorState(columns, errors, {
416	        questionId,
417	        rowId: row.rowId,
418	        rowIndex,
419	      }),
420	    [columns, errors, questionId, row.rowId, rowIndex],
421	  );
422	
423	  // Below `lg` the body wrapper — the ONLY place a cell's
424	  // `StructuredFieldError` renders — is `display:none` while collapsed. A
425	  // row a blocking `validate()` error binds to must never be hideable that
426	  // way: `useSubmitFillSession` aborts the whole submit on any
427	  // `QuestionValidationError`, so a collapsed row would leave only a bare
428	  // toast and the error's `role="alert"` would never be announced from a
429	  // hidden subtree. `hasError` wins over the clinician's own toggle, which
430	  // regains control the instant the error clears.
431	  const isExpanded = expanded || hasError;
432	
433	  // DEV-ONLY accessible-name audit — the enforcement
434	  // `StructuredControlProps` itself cannot provide (see its doc comment).
435	  // Audits the ACTUAL RENDERED DOM — true regardless of which mechanism,
436	  // or none, a column's `render` used. `[data-column="<key>"]` is markup
437	  // every cell already carries, so this adds no new DOM. Runs once per
438	  // render (no dependency array — a broken cell should log on every render
439	  // until it's fixed), body-scoped so it only inspects THIS row's cells,
440	  // and a complete no-op outside development builds.
441	  const bodyRef = useRef<HTMLDivElement>(null);
442	  useEffect(() => {
443	    if (!import.meta.env.DEV) return;
444	    const body = bodyRef.current;
445	    if (!body) return;
446	    for (const column of columns) {
447	      auditCellAccessibleName(body, {
448	        questionId,
449	        rowId: row.rowId,
450	        columnKey: column.key,
451	      });
452	    }
453	  });
454	
455	  return (
456	    <div
457	      role="row"
458	      data-structured-row={row.rowId}
459	      className={cn(
460	        "grid grid-cols-1 border-b border-gray-200 last:border-b-0 lg:grid-cols-[var(--structured-cols)] lg:hover:bg-gray-50/50",
461	        isDisabled && "pointer-events-none opacity-40",
462	        rowClassName?.(row),
463	      )}
464	    >
465	      {/* Mobile card chrome. role="none" keeps it OUT of the cell index,
466	          so getByRole("cell").nth(n) maps to the declared column order. */}
467	      <div role="none" className="lg:hidden">
468	        <button
469	          type="button"
470	          aria-expanded={isExpanded}
