export const meta = {
  name: 'cleanup-diff-review',
  description: 'Review the structured-core cleanup diff for regressions before commit',
  phases: [
    { title: 'Review', detail: '3 lenses over the uncommitted diff' },
    { title: 'Verify', detail: 'adversarial check of each finding' },
  ],
}

const ROOT = '/Users/bodhishthomas/code/care_fe'
const COMMON = `Repo: ${ROOT} (branch bodhi/questionnaire-fill). Review the UNCOMMITTED working diff (run: git -C ${ROOT} diff HEAD). Context: a deliberate cleanup of src/components/QuestionnaireV2/structured/ deleted verified-dead surface:
(S1) controller fields applyEdit/resetEdits/edits/isDirty/isDuplicate, option singletonRowId, StructuredList props removeLabel/canRemoveRow, StructuredColumn.className, ctx.removed;
(S2) resolveChanges' baseline param + orphan-drop + add-to-update reclassification (no caller ever passed a populated baseline);
(S3) truncateToSingletonRow replaced by a dev console.error assertion in useStructuredRows.composeWrite;
(S4) dedupeEditsFirstAppearance + downstream duplicate-rowId guards (sanitizeStructuredEditLog at the read gates is now the sole dedup);
(S5) error.index fallback + rowIndex plumbing in structured error matching, and QuestionValidationError.index;
(S6) useStructuredRows split into useStructuredRows (list) + useStructuredSingleRow wrappers over one internal impl — conditional return type and casts deleted;
(S8) the entire fill/assistant directory (3,164 LOC) + pluginTypes.formAssistant + PluginEngine registration + FillPageBody mount.
Deletion of dead code is INTENTIONAL — do not report "code was deleted" as a finding. Report ONLY defects: a deletion that changes behavior for a still-shipped flow, a missed reference (stale import/comment/doc that names deleted machinery), a test now pinning the wrong thing, a broken invariant, or an introduced bug in the edited code. Verification already done: tsc clean, eslint clean, unit suite 803/808 (5 pre-existing timezone child-process env failures), production build green. Your final output is data for a reviewer, not a human-facing message. Cite file:line.`

const FINDINGS = {
  type: 'object', additionalProperties: false,
  properties: {
    findings: { type: 'array', items: { type: 'object', properties: {
      title: {type:'string'}, file: {type:'string'}, line: {type:'number'},
      severity: {type:'string', enum:['high','medium','low']},
      detail: {type:'string'}, failureScenario: {type:'string'},
    }, required: ['title','file','line','severity','detail','failureScenario'] } },
  },
  required: ['findings'],
}

phase('Review')
const LENSES = [
  { key: 'behavior', prompt: `${COMMON}\n\nLENS: behavior preservation. For each deleted mechanism, trace the shipped flows that touched it (fill page editors, draft restore, submit compose, orphan prune, singleton discharge seed, mobile error display) and hunt for a case where the new code path produces different observable behavior. Pay special attention to: resolveChanges callers that previously relied on the empty-Map orphan drop for updates/removes they DO read; projectRows behavior for logs that can still legitimately contain shapes the deleted guards handled; the single-row wrapper returning row=rows[0] vs the old mode branch; the dev assertion using import.meta.env?.DEV under node --test and Vite prod builds.` },
  { key: 'references', prompt: `${COMMON}\n\nLENS: missed references. Sweep the WHOLE repo (src, tests, docs, README files, locale files public/locale/en.json, .env comments, playwright tests under tests/) for anything still referencing deleted identifiers or deleted files: FormAssistant, useFillAssistantSession, windowTestBridge, fill/assistant paths, applyEdit/resetEdits/isDuplicate as controller fields, truncateToSingletonRow, dedupeEditsFirstAppearance, error index fallback/rowIndex in structured matching, removeLabel/canRemoveRow, StructuredRowsController, mode: "single" passed to useStructuredRows. Also check for now-unused exports/imports/i18n keys the deletions orphaned (e.g. rowSchema-related plumbing is KNOWN to be consumer-less now — report where it stands but mark severity low).` },
  { key: 'tests', prompt: `${COMMON}\n\nLENS: test integrity. Read the modified test files in the diff (changes.test.ts, projectRows.test.ts, editLog.test.ts, structuredFieldErrors.test.ts, structuredListRowState.test.ts, useStructuredRows.orphanPrune.test.ts, useStructuredRows.initialEditsSeedTiming.test.ts, encounter/appointment/chargeItem model tests). Check: (a) no deleted test was actually pinning SURVIVING behavior (a real coverage loss); (b) rewritten tests (sanitize-gate pattern in encounter agreement/duplicate tests) still test what production does; (c) no test now passes vacuously; (d) the erasure-parity suite in deepEqual.test.ts still compiles against the surviving types.` },
]
const reviews = await parallel(LENSES.map(l => () =>
  agent(l.prompt, { label: `review:${l.key}`, phase: 'Review', schema: FINDINGS })))

const all = reviews.filter(Boolean).flatMap(r => r.findings)
log(`${all.length} raw findings — verifying`)

phase('Verify')
const VERDICT = {
  type: 'object', additionalProperties: false,
  properties: {
    verdict: {type:'string', enum:['CONFIRMED','REFUTED']},
    reasoning: {type:'string'},
    suggestedFix: {type:'string'},
  },
  required: ['verdict','reasoning','suggestedFix'],
}
const verified = await parallel(all.slice(0, 10).map(f => () =>
  agent(`${COMMON}\n\nAdversarially verify this finding by reading the actual current code. REFUTE it if the claimed defect does not exist, is pre-existing on HEAD (git show HEAD:<file>), or has no reachable consequence. CONFIRM only a real, introduced defect.\n\nFINDING: ${f.title}\nFILE: ${f.file}:${f.line}\nSEVERITY: ${f.severity}\nDETAIL: ${f.detail}\nFAILURE: ${f.failureScenario}`,
    { label: `verify:${f.title.slice(0, 30)}`, phase: 'Verify', schema: VERDICT })
    .then(v => ({ ...f, ...v }))))

return { findings: verified.filter(Boolean), unverifiedOverflow: all.slice(10) }

